SET NOCOUNT ON; SET LOCK_TIMEOUT 60000;
SELECT N'_Document152' table_name,
COUNT_BIG(j.[_IDRRef]) june_rows,
COUNT_BIG(s.[_IDRRef]) september_rows,
SUM(CONVERT(bigint,CASE WHEN j.[_IDRRef] IS NOT NULL AND s.[_IDRRef] IS NOT NULL THEN 1 ELSE 0 END)) [retained],
SUM(CONVERT(bigint,CASE WHEN s.[_IDRRef] IS NULL THEN 1 ELSE 0 END)) [removed],
SUM(CONVERT(bigint,CASE WHEN j.[_IDRRef] IS NULL THEN 1 ELSE 0 END)) [added],
SUM(CONVERT(bigint,CASE WHEN j.[_IDRRef] IS NOT NULL AND s.[_IDRRef] IS NOT NULL AND (CONVERT(varbinary(max),j.[_Number])<>CONVERT(varbinary(max),s.[_Number]) OR (j.[_Number] IS NULL AND s.[_Number] IS NOT NULL) OR (j.[_Number] IS NOT NULL AND s.[_Number] IS NULL)) THEN 1 ELSE 0 END)) [changed_Number],
SUM(CONVERT(bigint,CASE WHEN j.[_IDRRef] IS NOT NULL AND s.[_IDRRef] IS NOT NULL AND (CONVERT(varbinary(max),j.[_Date_Time])<>CONVERT(varbinary(max),s.[_Date_Time]) OR (j.[_Date_Time] IS NULL AND s.[_Date_Time] IS NOT NULL) OR (j.[_Date_Time] IS NOT NULL AND s.[_Date_Time] IS NULL)) THEN 1 ELSE 0 END)) [changed_Date_Time],
SUM(CONVERT(bigint,CASE WHEN j.[_IDRRef] IS NOT NULL AND s.[_IDRRef] IS NOT NULL AND (CONVERT(varbinary(max),j.[_Posted])<>CONVERT(varbinary(max),s.[_Posted]) OR (j.[_Posted] IS NULL AND s.[_Posted] IS NOT NULL) OR (j.[_Posted] IS NOT NULL AND s.[_Posted] IS NULL)) THEN 1 ELSE 0 END)) [changed_Posted],
SUM(CONVERT(bigint,CASE WHEN j.[_IDRRef] IS NOT NULL AND s.[_IDRRef] IS NOT NULL AND (CONVERT(varbinary(max),j.[_Marked])<>CONVERT(varbinary(max),s.[_Marked]) OR (j.[_Marked] IS NULL AND s.[_Marked] IS NOT NULL) OR (j.[_Marked] IS NOT NULL AND s.[_Marked] IS NULL)) THEN 1 ELSE 0 END)) [changed_Marked],
SUM(CONVERT(bigint,CASE WHEN j.[_IDRRef] IS NOT NULL AND s.[_IDRRef] IS NOT NULL AND (CONVERT(varbinary(max),j.[_Fld1080])<>CONVERT(varbinary(max),s.[_Fld1080]) OR (j.[_Fld1080] IS NULL AND s.[_Fld1080] IS NOT NULL) OR (j.[_Fld1080] IS NOT NULL AND s.[_Fld1080] IS NULL)) THEN 1 ELSE 0 END)) [changed_Fld1080],
SUM(CONVERT(bigint,CASE WHEN j.[_IDRRef] IS NOT NULL AND s.[_IDRRef] IS NOT NULL AND (CONVERT(varbinary(max),j.[_Fld1057_RRRef])<>CONVERT(varbinary(max),s.[_Fld1057_RRRef]) OR (j.[_Fld1057_RRRef] IS NULL AND s.[_Fld1057_RRRef] IS NOT NULL) OR (j.[_Fld1057_RRRef] IS NOT NULL AND s.[_Fld1057_RRRef] IS NULL)) THEN 1 ELSE 0 END)) [changed_Fld1057_RRRef],
SUM(CONVERT(bigint,CASE WHEN j.[_IDRRef] IS NOT NULL AND s.[_IDRRef] IS NOT NULL AND (CONVERT(varbinary(max),j.[_Fld1058RRef])<>CONVERT(varbinary(max),s.[_Fld1058RRef]) OR (j.[_Fld1058RRef] IS NULL AND s.[_Fld1058RRef] IS NOT NULL) OR (j.[_Fld1058RRef] IS NOT NULL AND s.[_Fld1058RRef] IS NULL)) THEN 1 ELSE 0 END)) [changed_Fld1058RRef],
SUM(CONVERT(bigint,CASE WHEN j.[_IDRRef] IS NOT NULL AND s.[_IDRRef] IS NOT NULL AND (CONVERT(varbinary(max),j.[_Fld1074RRef])<>CONVERT(varbinary(max),s.[_Fld1074RRef]) OR (j.[_Fld1074RRef] IS NULL AND s.[_Fld1074RRef] IS NOT NULL) OR (j.[_Fld1074RRef] IS NOT NULL AND s.[_Fld1074RRef] IS NULL)) THEN 1 ELSE 0 END)) [changed_Fld1074RRef] FROM [FitnessRestored_20260630_original].dbo.[_Document152] j FULL JOIN [FitnessRestored_20260630_macos].dbo.[_Document152] s ON j.[_IDRRef]=s.[_IDRRef] FOR JSON PATH, INCLUDE_NULL_VALUES;
